def regex_search(pattern: str, text: str) -> bool:
    p = pattern
    n_pat = len(p)
    n_text = len(text)
    idx = 0

    def parse_alt(in_group: bool):
        nonlocal idx
        branches = [parse_sequence(in_group)]
        while idx < n_pat and p[idx] == '|':
            idx += 1
            branches.append(parse_sequence(in_group))
        if len(branches) == 1:
            return branches[0]
        return ('alt', branches)

    def parse_sequence(in_group: bool):
        nonlocal idx
        items = []
        last = None

        while idx < n_pat:
            c = p[idx]

            if c == '|':
                break

            if c == ')':
                if in_group:
                    break
                raise ValueError

            if c in '*+?':
                if last is None:
                    raise ValueError
                if last[0] == 'rep' or last[0] == 'start_anchor' or last[0] == 'end_anchor':
                    raise ValueError

                kind = c
                idx += 1
                items[-1] = ('rep', kind, items[-1])
                last = items[-1]
                continue

            node = parse_element()
            items.append(node)
            last = node

        if not items:
            return ('seq', [])
        if len(items) == 1:
            return items[0]
        return ('seq', items)

    def parse_element():
        nonlocal idx

        if idx >= n_pat:
            raise ValueError

        c = p[idx]

        if c == '(':
            idx += 1
            child = parse_alt(True)
            if idx >= n_pat or p[idx] != ')':
                raise ValueError
            idx += 1
            return ('group', child)

        if c == '[':
            neg, items = parse_class()
            return ('class', neg, items)

        if c == '.':
            idx += 1
            return ('any',)

        if c == '^':
            idx += 1
            return ('start_anchor',)

        if c == '$':
            idx += 1
            return ('end_anchor',)

        if c == '\\':
            if idx + 1 >= n_pat:
                raise ValueError
            ch = p[idx + 1]
            idx += 2
            return ('lit', ch)

        idx += 1
        return ('lit', c)

    def parse_class():
        nonlocal idx

        idx += 1  # skip '['
        neg = False

        if idx < n_pat and p[idx] == '^':
            neg = True
            idx += 1

        items = []

        if idx >= n_pat or p[idx] == ']':
            raise ValueError

        first_item = True

        while True:
            if idx >= n_pat:
                raise ValueError

            if p[idx] == ']':
                if not items:
                    raise ValueError
                idx += 1
                return neg, items

            if p[idx] == '\\':
                if idx + 1 >= n_pat:
                    raise ValueError
                x = p[idx + 1]
                idx += 2
            else:
                x = p[idx]
                idx += 1

            if not (first_item and x == '-'):
                if idx < n_pat and p[idx] == '-' and idx + 1 < n_pat and p[idx + 1] != ']':
                    if p[idx + 1] == '\\':
                        if idx + 2 >= n_pat:
                            raise ValueError
                        y = p[idx + 2]
                        idx += 3
                    else:
                        y = p[idx + 1]
                        idx += 2

                    x_ord = ord(x)
                    y_ord = ord(y)
                    if x_ord > y_ord:
                        raise ValueError
                    items.append(('range', x_ord, y_ord))
                else:
                    items.append(('char', ord(x)))

            first_item = False

    def new_state():
        eps.append([])
        anchor.append(None)
        match.append(None)
        accept.append(False)
        return len(eps) - 1

    eps = []
    anchor = []
    match = []
    accept = []

    def compile_node(node):
        kind = node[0]

        if kind == 'seq':
            start = new_state()
            if not node[1]:
                end = new_state()
                eps[start].append(end)
                return start, end

            cur = start
            for child in node[1]:
                s, e = compile_node(child)
                eps[cur].append(s)
                cur = e

            return start, cur

        if kind == 'alt':
            start = new_state()
            end = new_state()
            for branch in node[1]:
                s, e = compile_node(branch)
                eps[start].append(s)
                eps[e].append(end)
            return start, end

        if kind == 'group':
            return compile_node(node[1])

        if kind == 'rep':
            quantifier = node[1]
            base_start, base_end = compile_node(node[2])
            start = new_state()
            end = new_state()

            if quantifier == '*':
                eps[start].append(end)
                eps[start].append(base_start)
                eps[base_end].append(base_start)
                eps[base_end].append(end)
            elif quantifier == '+':
                eps[start].append(base_start)
                eps[base_end].append(base_start)
                eps[base_end].append(end)
            else:
                eps[start].append(base_start)
                eps[start].append(end)
                eps[base_end].append(end)

            return start, end

        if kind == 'lit':
            s = new_state()
            e = new_state()
            match[s] = ('lit', node[1], e)
            return s, e

        if kind == 'any':
            s = new_state()
            e = new_state()
            match[s] = ('any', e)
            return s, e

        if kind == 'class':
            s = new_state()
            e = new_state()
            match[s] = ('class', node[1], node[2], e)
            return s, e

        if kind == 'start_anchor':
            s = new_state()
            e = new_state()
            anchor[s] = 'start'
            eps[s].append(e)
            return s, e

        if kind == 'end_anchor':
            s = new_state()
            e = new_state()
            anchor[s] = 'end'
            eps[s].append(e)
            return s, e

        raise ValueError

    def class_matches(c, neg, items):
        cp = ord(c)
        hit = False
        for item in items:
            if item[0] == 'char':
                if cp == item[1]:
                    hit = True
                    break
            else:
                lo, hi = item[1], item[2]
                if lo <= cp <= hi:
                    hit = True
                    break

        return (not hit) if neg else hit

    def closure(states, pos):
        res = set(states)
        stack = list(res)

        while stack:
            s = stack.pop()

            if anchor[s] == 'start' and pos != 0:
                continue
            if anchor[s] == 'end' and pos != n_text:
                continue

            for t in eps[s]:
                if t not in res:
                    res.add(t)
                    stack.append(t)

        return res

    root = parse_alt(False)
    if idx != n_pat:
        raise ValueError

    start, final = compile_node(root)
    accept[final] = True

    states = set()

    for pos in range(n_text + 1):
        if states:
            states.add(start)
        else:
            states = {start}

        states = closure(states, pos)

        for s in states:
            if accept[s]:
                return True

        if pos == n_text:
            break

        c = text[pos]
        nxt = set()

        for s in states:
            mt = match[s]
            if mt is None:
                continue

            if mt[0] == 'lit':
                if c == mt[1]:
                    nxt.add(mt[2])
            elif mt[0] == 'any':
                nxt.add(mt[1])
            else:
                if class_matches(c, mt[1], mt[2]):
                    nxt.add(mt[3])

        states = nxt

    return False
